import { useCallback, useEffect, useState } from 'react'

import type { Expense, ExpenseDraft, ExpenseGateway, FieldErrors } from '../../application/expense'
import { loadExpenses, submitExpense } from '../../application/expenseUseCases'

export const useExpenses = (gateway: ExpenseGateway) => {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({})
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  const refresh = useCallback(async () => {
    try {
      setExpenses(await loadExpenses(gateway))
      setLoadError(null)
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : 'Could not load expenses')
    } finally {
      setLoading(false)
    }
  }, [gateway])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void refresh()
  }, [refresh])

  const submit = async (draft: ExpenseDraft): Promise<boolean> => {
    setSubmitting(true)
    setSubmitError(null)
    try {
      const result = await submitExpense(gateway, draft)
      setFieldErrors(result.ok ? {} : result.errors)
      if (result.ok) await refresh()
      return result.ok
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : 'Could not submit expense')
      return false
    } finally {
      setSubmitting(false)
    }
  }

  return { expenses, loading, loadError, fieldErrors, submitError, submitting, submit }
}
