import { useState } from 'react'
import type { FormEvent } from 'react'

import type { ExpenseDraft, FieldErrors } from '../../application/expense'

type Props = {
  errors: FieldErrors
  submitting: boolean
  onSubmit: (draft: ExpenseDraft) => Promise<boolean>
}

const empty: ExpenseDraft = { label: '', amount: '', currency: 'EUR' }

export const ExpenseForm = ({ errors, submitting, onSubmit }: Props) => {
  const [draft, setDraft] = useState<ExpenseDraft>(empty)

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()
    if (await onSubmit(draft)) setDraft(empty)
  }

  const field = (name: keyof ExpenseDraft, label: string, type: string) => (
    <div>
      <label htmlFor={`expense-${name}`}>{label}</label>
      <input
        id={`expense-${name}`}
        name={name}
        type={type}
        value={draft[name]}
        aria-invalid={errors[name] ? true : undefined}
        aria-describedby={errors[name] ? `expense-${name}-error` : undefined}
        onChange={(event) => setDraft({ ...draft, [name]: event.target.value })}
      />
      {errors[name] ? (
        <span id={`expense-${name}-error`} role="alert">
          {errors[name]}
        </span>
      ) : null}
    </div>
  )

  return (
    <form onSubmit={handleSubmit} noValidate>
      {field('label', 'Label', 'text')}
      {field('amount', 'Amount', 'number')}
      {field('currency', 'Currency', 'text')}
      <button type="submit" disabled={submitting}>
        Submit expense
      </button>
    </form>
  )
}
