import type { Expense, ExpenseDraft, ExpenseGateway, FieldErrors } from './expense'
import { ValidationError } from './expense'

export const loadExpenses = (gateway: ExpenseGateway): Promise<Expense[]> => gateway.list()

export type SubmitResult = { ok: true } | { ok: false; errors: FieldErrors }

export const submitExpense = async (gateway: ExpenseGateway, draft: ExpenseDraft): Promise<SubmitResult> => {
  const amount = Number(draft.amount)
  if (draft.amount.trim() === '' || !Number.isFinite(amount)) {
    return { ok: false, errors: { amount: 'Amount must be a number' } }
  }
  try {
    await gateway.create({ label: draft.label.trim(), amount, currency: draft.currency.trim() })
    return { ok: true }
  } catch (error) {
    if (error instanceof ValidationError) return { ok: false, errors: error.errors }
    throw error
  }
}
